package net.officefloor.hq.app.template;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.session.CurrentUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimTemplateController {

    /** A template as the screen shows it: its name, its amount with two decimals and its note. */
    public record TemplateView(String name, String amount, String note) {
        static TemplateView of(ClaimTemplate t) {
            return new TemplateView(t.getName(), t.getAmount().setScale(2).toPlainString(), t.getNote());
        }
    }

    /** A template as the form submits it: a name (not blank), an amount the claim form takes for
     *  a new claim (0.00 or more, up to two decimals), and an optional note. */
    public record TemplateForm(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "\\s*\\d{1,13}(\\.\\d{1,2})?\\s*") String amount,
            @Size(max = 1000) String note) {
    }

    /** The name of the template a claim is made from. */
    public record FromTemplateForm(@NotBlank @Size(max = 200) String template) {
    }

    private final ClaimTemplateService service;
    private final ClaimController claims;

    public ClaimTemplateController(ClaimTemplateService service, ClaimController claims) {
        this.service = service;
        this.claims = claims;
    }

    @GetMapping("/templates")
    public List<TemplateView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        return service.list(sheetId).stream().map(TemplateView::of).toList();
    }

    /** Save a template; resolves to the sheet's templates with it. */
    @PutMapping("/templates")
    public List<TemplateView> save(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody TemplateForm body) {
        service.save(sheetId, user.trim(), body.name().trim(), new BigDecimal(body.amount().trim()), body.note());
        return list(sheetId, user);
    }

    @PostMapping("/people/{personId}/claims/from-template")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView addClaim(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody FromTemplateForm body) {
        return claims.view(service.addClaim(sheetId, user.trim(), personId, body.template().trim()));
    }
}
package net.officefloor.hq.app.template;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;

/** A claim template on the sheet: a claim made from it is given its amount and note as they are then. */
@Entity
@Table(name = "claim_template")
public class ClaimTemplate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "amount", nullable = false, precision = 15, scale = 2)
    private BigDecimal amount;

    @Column(name = "note", nullable = false)
    private String note;

    protected ClaimTemplate() {
    }

    public ClaimTemplate(String sheetId, String name, BigDecimal amount, String note) {
        this.sheetId = sheetId;
        this.name = name;
        this.amount = amount;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public String getNote() {
        return note;
    }

    /** Replace the template's amount and note. */
    public void replace(BigDecimal amount, String note) {
        this.amount = amount;
        this.note = note;
    }
}
package net.officefloor.hq.app.template;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface ClaimTemplateRepository extends JpaRepository<ClaimTemplate, Long> {

    /** The sheet's templates, by name. */
    List<ClaimTemplate> findBySheetIdOrderByNameAsc(String sheetId);

    Optional<ClaimTemplate> findBySheetIdAndName(String sheetId, String name);
}
package net.officefloor.hq.app.template;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ClaimTemplateService {

    private final ClaimTemplateRepository templates;
    private final ClaimService claims;
    private final SheetService sheets;
    private final Audit audit;

    public ClaimTemplateService(ClaimTemplateRepository templates, ClaimService claims, SheetService sheets, Audit audit) {
        this.templates = templates;
        this.claims = claims;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's templates, by name. */
    @Transactional(readOnly = true)
    public List<ClaimTemplate> list(String sheetId) {
        return templates.findBySheetIdOrderByNameAsc(sheetId);
    }

    /** Save a template on the sheet, the sheet created first if it was never loaded; a name saved
     *  already has its amount and note replaced. */
    @Transactional
    public ClaimTemplate save(String sheetId, String user, String name, BigDecimal amount, String note) {
        sheets.load(sheetId, user);
        sheets.lock(sheetId);
        String trimmedNote = note == null ? "" : note.trim();
        ClaimTemplate template = templates.findBySheetIdAndName(sheetId, name).orElse(null);
        if (template == null) {
            template = templates.saveAndFlush(new ClaimTemplate(sheetId, name, amount, trimmedNote));
        } else {
            template.replace(amount, trimmedNote);
            templates.flush();
        }
        audit.recordOnCommit("TEMPLATE_SAVED sheet=" + sheetId + " by=" + user + " name=" + name
                + " amount=" + amount.setScale(2).toPlainString() + " note=" + trimmedNote);
        return template;
    }

    /** Add a DRAFT claim for the person with the template's amount and note as they are now, dated
     *  as a claim added with no date, by every rule of the claim form; refused (404) when the
     *  sheet has no template of the name. */
    @Transactional
    public Claim addClaim(String sheetId, String user, long personId, String name) {
        ClaimTemplate template = templates.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such template"));
        return claims.add(sheetId, user, personId, template.getAmount(), null, template.getNote(), null, null, null);
    }
}
-- A claim template on the sheet: a name (at most once per sheet), the amount and note a claim made
-- from it is given. Saving a name again replaces its amount and note; claims made earlier keep theirs.
CREATE TABLE claim_template (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    amount    DECIMAL(15, 2) NOT NULL,
    note      VARCHAR(1000) NOT NULL,
    UNIQUE (sheet_id, name)
);
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, otherError } from '../../core/session';

/** A claim template: a claim made from it is given its amount (two decimals) and note as they are then. */
export interface ClaimTemplate {
  name: string;
  amount: string;
  note: string;
}

@Injectable({ providedIn: 'root' })
export class TemplatesApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's templates, by name. */
  list(sheetId: string): Promise<ClaimTemplate[]> {
    return firstValueFrom(this.http.get<ClaimTemplate[]>(`${this.url(sheetId)}/templates`, { headers: this.headers() }));
  }

  /** Save a template, replacing one of the same name; resolves to the sheet's templates with it. */
  save(sheetId: string, form: ClaimTemplate): Promise<ClaimTemplate[]> {
    return firstValueFrom(this.http.put<ClaimTemplate[]>(`${this.url(sheetId)}/templates`, form, { headers: this.headers() }));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function templateError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a name and an amount of 0.00 or more with up to two decimals.';
  return otherError(e);
}
import { Component, effect, inject, signal, untracked } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { AMOUNT_PATTERN } from '../claims/claims-api';
import { TemplatesApi, templateError } from './templates-api';

